"""
date_utils.py - Dienst fuer Datumsoperationen.

Verwendung:
    from core_services.utils import convert_iso_to_datetime, get_last_quarter_dates, is_first_sunday_of_quarter
"""

import logging
from datetime import UTC, date, datetime, timedelta
from typing import cast
from zoneinfo import ZoneInfo

import pandas as pd

logger = logging.getLogger(__name__)

BERLIN_TIMEZONE = ZoneInfo("Europe/Berlin")


def coerce_to_datetime(value: date | datetime | pd.Timestamp | str | None, field_name: str = "value") -> datetime:
    """Konvertiert gaengige datumsartige Werte in ein timezone-nahes datetime fuer sichere Vergleiche.

    Zeitzonenbehaftete Werte werden nach Europe/Berlin konvertiert und die Zeitzone
    anschliessend entfernt, sodass ein naives datetime zurueckgegeben wird.

    Args:
        value: Zu konvertierender Wert (datetime, date, pd.Timestamp, str oder None).
        field_name: Name des Feldes fuer Fehlermeldungen.

    Returns:
        Naives datetime-Objekt.

    Raises:
        ValueError: Wenn value None ist.
        TypeError: Wenn der Typ nicht unterstuetzt wird.
    """
    if value is None:
        raise ValueError(f"{field_name} darf nicht None sein")

    if isinstance(value, pd.Timestamp):
        value = value.to_pydatetime()

    if isinstance(value, datetime):
        if value.tzinfo is not None:
            return value.astimezone(BERLIN_TIMEZONE).replace(tzinfo=None)
        return value

    if isinstance(value, date):
        return datetime.combine(value, datetime.min.time())

    if isinstance(value, str):
        text = value.strip()
        if text.endswith("Z"):
            text = text[:-1] + "+00:00"

        parsed = pd.to_datetime(text, errors="raise")
        if isinstance(parsed, pd.Timestamp):
            dt = cast(datetime, parsed.to_pydatetime())
            if dt.tzinfo is not None:
                return dt.astimezone(BERLIN_TIMEZONE).replace(tzinfo=None)
            return dt

    raise TypeError(f"{field_name} hat einen nicht unterstuetzten Typ: {type(value)}")


def convert_iso_to_datetime(iso_string: str | None) -> datetime | None:
    """Konvertiert einen ISO-Datumsstring in ein datetime-Objekt.

    Unterstuetzt verschiedene ISO-Formate (mit/ohne Zeitzone, mit 'Z'-Suffix).

    Args:
        iso_string: ISO-Datumsstring, z. B. "2024-01-15T10:30:00+01:00".

    Returns:
        Konvertiertes datetime-Objekt oder None bei leerem Input oder Fehler.
    """
    if not iso_string:
        return None

    try:
        normalized = iso_string.replace("Z", "+00:00")
        if "+" not in normalized[-6:] and "-" not in normalized[-6:]:
            normalized += "+00:00"
        return datetime.fromisoformat(normalized)
    except (ValueError, AttributeError) as exc:
        logger.warning("Datum konnte nicht konvertiert werden: %s, Fehler: %s", iso_string, exc)
        return None


def is_first_sunday_of_quarter(date: date | None = None) -> bool:
    """Prueft, ob ein gegebenes Datum der erste Sonntag eines Quartals ist.

    Args:
        date: Zu pruefendes Datum. Bei None wird das heutige Datum verwendet.

    Returns:
        True, wenn das Datum der erste Sonntag eines Quartals ist, sonst False.
    """
    if date is None:
        date = datetime.now(BERLIN_TIMEZONE).date()

    year = date.year
    month = date.month
    quarter_start_month = ((month - 1) // 3) * 3 + 1
    first_of_quarter = datetime(year, quarter_start_month, 1).date()
    days_until_sunday = (6 - first_of_quarter.weekday()) % 7
    first_sunday = first_of_quarter + timedelta(days=days_until_sunday)
    return date == first_sunday


def get_last_quarter_dates() -> tuple[str, str]:
    """Berechnet das Start- und Enddatum des letzten Quartals.

    Returns:
        Tuple (start_date, end_date) im Format "YYYY-MM-DD".
    """
    now = datetime.now(BERLIN_TIMEZONE)
    current_quarter = (now.month - 1) // 3 + 1

    if current_quarter == 1:
        last_quarter = 4
        year = now.year - 1
    else:
        last_quarter = current_quarter - 1
        year = now.year

    first_month = 3 * (last_quarter - 1) + 1
    start_date = datetime(year, first_month, 1)

    if last_quarter == 4:
        end_date = datetime(year + 1, 1, 1) - timedelta(days=1)
    else:
        end_date = datetime(year, first_month + 3, 1) - timedelta(days=1)

    return start_date.strftime("%Y-%m-%d"), end_date.strftime("%Y-%m-%d")


def berlin_datetime_to_utc_api_value(date_value: str) -> str:
    """Interpretiert ein Datum als Berliner Zeit und formatiert es fuer die API in UTC."""
    utc_date = berlin_datetime_to_utc(date_value)
    return utc_date.replace(tzinfo=None).isoformat(timespec="seconds") + " "


def berlin_renewal_day_from_date(date_value: str) -> int:
    """Ermittelt den Renewal-Day aus dem nach UTC umgerechneten Datum."""
    utc_date = berlin_datetime_to_utc(date_value)
    return utc_date.day


def berlin_datetime_to_utc(date_value: str) -> datetime:
    """Interpretiert ein Datum als Berliner Zeit und gibt es als UTC-Datum zurueck."""
    value = date_value.strip()
    try:
        parsed_date = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError as exc:
        raise ValueError(f"Datum hat kein gueltiges Datumsformat: {date_value}") from exc

    if parsed_date.tzinfo is None:
        parsed_date = parsed_date.replace(tzinfo=BERLIN_TIMEZONE)

    return parsed_date.astimezone(UTC)
